SET @r2_checks='[{"t":"exercise_result","s":1,"n":"ck_exercise_result_complete","e":"is_complete IN (0,1)"},{"t":"chat_conversations","s":1,"n":"ck_chat_participant_order","e":"participant_one_id < participant_two_id"},{"t":"chat_conversations","s":1,"n":"ck_chat_conversation_type","e":"conversation_type IN (''THERAPIST'',''PEER'')"},{"t":"custom_exercise_assignments","s":1,"n":"ck_custom_assignment_active","e":"is_active IN (0,1)"},{"t":"exercise_assignments","s":1,"n":"ck_exercise_assignment_active","e":"is_active IN (0,1)"},{"t":"rehab_plans","s":1,"n":"ck_rehab_plan_condition","e":"condition_type IN (''fracture'',''stroke'')"},{"t":"rehab_plan_items","s":1,"n":"ck_rehab_plan_item_order","e":"item_order >= 0"},{"t":"rehab_plan_items","s":1,"n":"ck_rehab_plan_item_sets","e":"sets > 0"},{"t":"rehab_plan_items","s":1,"n":"ck_rehab_plan_item_reps","e":"reps_per_set > 0"},{"t":"rehab_plan_items","s":1,"n":"ck_rehab_plan_item_done","e":"done IN (0,1)"},{"t":"training_history_video","s":1,"n":"ck_training_video_size","e":"file_size > 0"},{"t":"user_avatars","s":1,"n":"ck_user_avatar_source","e":"source_type IN (''CUSTOM'',''GOOGLE'')"},{"t":"research_consents","s":2,"n":"ck_research_consent_active","e":"active IN (0,1)"},{"t":"research_grants","s":2,"n":"ck_research_grant_annotate","e":"can_annotate IN (0,1)"},{"t":"research_grants","s":2,"n":"ck_research_grant_review","e":"can_review IN (0,1)"},{"t":"research_grants","s":2,"n":"ck_research_grant_manage","e":"can_manage IN (0,1)"}]';
WITH expected AS (SELECT * FROM JSON_TABLE(@r2_tables, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s')) j WHERE s<=@r2_stage)
SELECT 'TABLE_DRIFT' AS audit, e.t, a.ENGINE, a.TABLE_COLLATION
FROM expected e LEFT JOIN information_schema.TABLES a ON a.TABLE_SCHEMA=DATABASE() AND a.TABLE_NAME=e.t
WHERE a.TABLE_NAME IS NULL OR a.ENGINE<>'InnoDB' OR a.TABLE_COLLATION<>'utf8mb4_0900_as_cs'
UNION ALL SELECT 'EXTRA_TABLE', a.TABLE_NAME, a.ENGINE, a.TABLE_COLLATION
FROM information_schema.TABLES a LEFT JOIN expected e ON e.t=a.TABLE_NAME
WHERE a.TABLE_SCHEMA=DATABASE() AND e.t IS NULL;

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_columns, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', typ VARCHAR(64) PATH '$.typ', nullable VARCHAR(3) PATH '$.nullable', d VARCHAR(100) PATH '$.d', auto INT PATH '$.auto', gen VARCHAR(300) PATH '$.gen', storage VARCHAR(10) PATH '$.storage', coll VARCHAR(64) PATH '$.coll')) j WHERE s<=@r2_stage)
SELECT 'COLUMN_DRIFT' AS audit, e.t, e.n, e.typ AS expected_type, a.COLUMN_TYPE AS actual_type,
e.nullable AS expected_nullable, a.IS_NULLABLE AS actual_nullable, e.d AS expected_default, a.COLUMN_DEFAULT AS actual_default,
a.EXTRA, a.GENERATION_EXPRESSION, a.COLLATION_NAME
FROM expected e LEFT JOIN information_schema.COLUMNS a ON a.TABLE_SCHEMA=DATABASE() AND a.TABLE_NAME=e.t AND a.COLUMN_NAME=e.n
WHERE a.COLUMN_NAME IS NULL OR a.COLUMN_TYPE<>e.typ OR a.IS_NULLABLE<>e.nullable
OR NOT (LOWER(REGEXP_REPLACE(REPLACE(COALESCE(a.COLUMN_DEFAULT,''),'_utf8mb4',''),'[[:space:]`()]+','')) <=> LOWER(REGEXP_REPLACE(REPLACE(COALESCE(e.d,''),'_utf8mb4',''),'[[:space:]`()]+','')))
OR (LOCATE('auto_increment',a.EXTRA)>0)<>e.auto
OR LOWER(REGEXP_REPLACE(REPLACE(COALESCE(a.GENERATION_EXPRESSION,''),'_utf8mb4',''),'[[:space:]`()]+',''))<>LOWER(REGEXP_REPLACE(REPLACE(COALESCE(e.gen,''),'_utf8mb4',''),'[[:space:]`()]+',''))
OR (e.storage<>'' AND LOCATE(CONCAT(e.storage,' GENERATED'),UPPER(a.EXTRA))=0)
OR (e.storage='' AND LOCATE('GENERATED',UPPER(a.EXTRA))>0 AND LOCATE('DEFAULT_GENERATED',UPPER(a.EXTRA))=0)
OR NOT (a.COLLATION_NAME <=> e.coll);

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_columns, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', typ VARCHAR(64) PATH '$.typ', nullable VARCHAR(3) PATH '$.nullable', d VARCHAR(100) PATH '$.d', auto INT PATH '$.auto', gen VARCHAR(300) PATH '$.gen', storage VARCHAR(10) PATH '$.storage', coll VARCHAR(64) PATH '$.coll')) j WHERE s<=@r2_stage)
SELECT 'EXTRA_COLUMN' AS audit, a.TABLE_NAME, a.COLUMN_NAME
FROM information_schema.COLUMNS a LEFT JOIN expected e ON a.TABLE_NAME=e.t AND a.COLUMN_NAME=e.n
WHERE a.TABLE_SCHEMA=DATABASE() AND e.n IS NULL;

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_indexes, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', uq INT PATH '$.unique', c VARCHAR(512) PATH '$.c')) j WHERE s<=@r2_stage)
, actual AS (
SELECT TABLE_NAME t, INDEX_NAME n, MIN(NON_UNIQUE) non_unique,
GROUP_CONCAT(CONCAT(COLUMN_NAME,IF(COLLATION='D',' DESC',' ASC')) ORDER BY SEQ_IN_INDEX SEPARATOR ',') c,
SUM(SUB_PART IS NOT NULL) prefixes, MIN(IS_VISIBLE) visible, MIN(INDEX_TYPE) kind
FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() GROUP BY TABLE_NAME,INDEX_NAME)
SELECT 'INDEX_DRIFT' AS audit, e.t, e.n, e.c AS expected_columns, a.c AS actual_columns
FROM expected e LEFT JOIN actual a ON a.t=e.t AND a.n=e.n
WHERE a.n IS NULL OR a.non_unique<>1-e.uq OR a.c<>e.c OR a.prefixes<>0 OR a.visible<>'YES' OR a.kind<>'BTREE';

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_fks, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', c VARCHAR(64) PATH '$.c', rt VARCHAR(64) PATH '$.rt', rc VARCHAR(64) PATH '$.rc', d VARCHAR(16) PATH '$.d', u VARCHAR(16) PATH '$.u')) j WHERE s<=@r2_stage)
SELECT 'FK_DRIFT' AS audit, e.t, e.n, e.c, e.rt, e.rc, r.DELETE_RULE, r.UPDATE_RULE
FROM expected e LEFT JOIN information_schema.KEY_COLUMN_USAGE k
ON k.CONSTRAINT_SCHEMA=DATABASE() AND k.TABLE_NAME=e.t AND k.CONSTRAINT_NAME=e.n
LEFT JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=DATABASE() AND r.CONSTRAINT_NAME=e.n AND r.TABLE_NAME=e.t
WHERE k.CONSTRAINT_NAME IS NULL OR k.COLUMN_NAME<>e.c OR k.REFERENCED_TABLE_SCHEMA<>DATABASE()
OR k.REFERENCED_TABLE_NAME<>e.rt OR k.REFERENCED_COLUMN_NAME<>e.rc
OR REPLACE(r.DELETE_RULE,'NO ACTION','RESTRICT')<>e.d OR REPLACE(r.UPDATE_RULE,'NO ACTION','RESTRICT')<>e.u;

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_fks, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', c VARCHAR(64) PATH '$.c', rt VARCHAR(64) PATH '$.rt', rc VARCHAR(64) PATH '$.rc', d VARCHAR(16) PATH '$.d', u VARCHAR(16) PATH '$.u')) j WHERE s<=@r2_stage)
SELECT 'EXTRA_FK' AS audit, a.TABLE_NAME, a.CONSTRAINT_NAME
FROM information_schema.REFERENTIAL_CONSTRAINTS a LEFT JOIN expected e ON a.TABLE_NAME=e.t AND a.CONSTRAINT_NAME=e.n
WHERE a.CONSTRAINT_SCHEMA=DATABASE() AND e.n IS NULL;

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_checks, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', e VARCHAR(512) PATH '$.e')) j WHERE s<=@r2_stage)
SELECT 'CHECK_DRIFT' AS audit, e.t, e.n, e.e AS expected_clause, a.CHECK_CLAUSE AS actual_clause, tc.ENFORCED
FROM expected e LEFT JOIN information_schema.CHECK_CONSTRAINTS a ON a.CONSTRAINT_SCHEMA=DATABASE() AND a.CONSTRAINT_NAME=e.n
LEFT JOIN information_schema.TABLE_CONSTRAINTS tc ON tc.CONSTRAINT_SCHEMA=DATABASE() AND tc.TABLE_NAME=e.t AND tc.CONSTRAINT_NAME=e.n
WHERE a.CONSTRAINT_NAME IS NULL OR tc.ENFORCED<>'YES' OR REGEXP_REPLACE(REGEXP_REPLACE(REPLACE(COALESCE(a.CHECK_CLAUSE,''),'_utf8mb4',''),'[[:space:]]+IN[[:space:]]+',' in ',1,0,'i'),'[[:space:]`()]+','')<>REGEXP_REPLACE(REGEXP_REPLACE(REPLACE(COALESCE(e.e,''),'_utf8mb4',''),'[[:space:]]+IN[[:space:]]+',' in ',1,0,'i'),'[[:space:]`()]+','');

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_checks, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', e VARCHAR(512) PATH '$.e')) j WHERE s<=@r2_stage)
SELECT 'EXTRA_CHECK' AS audit, a.TABLE_NAME, a.CONSTRAINT_NAME
FROM information_schema.TABLE_CONSTRAINTS a LEFT JOIN expected e ON a.TABLE_NAME=e.t AND a.CONSTRAINT_NAME=e.n
WHERE a.CONSTRAINT_SCHEMA=DATABASE() AND a.CONSTRAINT_TYPE='CHECK' AND e.n IS NULL;

WITH expected AS (SELECT * FROM JSON_TABLE(@r2_indexes, '$[*]' COLUMNS (t VARCHAR(64) PATH '$.t', s INT PATH '$.s', n VARCHAR(64) PATH '$.n', uq INT PATH '$.unique', c VARCHAR(512) PATH '$.c')) j WHERE s<=@r2_stage)
SELECT 'UNEXPECTED_INDEX_REVIEW' AS audit, a.TABLE_NAME, a.INDEX_NAME, a.NON_UNIQUE, a.COLUMN_NAME
FROM information_schema.STATISTICS a LEFT JOIN expected e ON a.TABLE_NAME=e.t AND a.INDEX_NAME=e.n
WHERE a.TABLE_SCHEMA=DATABASE() AND e.n IS NULL ORDER BY a.TABLE_NAME,a.INDEX_NAME,a.SEQ_IN_INDEX;
SELECT COUNT(*) AS actual_base_tables, IF(@r2_stage=1,18,29) AS expected_base_tables
FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE';
